import React, { createContext, useState, useContext, useEffect } from 'react';

// Traductions complètes
const translations = {
  mg: {
    appName: 'Mpanolo-tsaina AI',
    slogan: 'Mpanampy amin\'ny fahaizana mamaky sy mandinika ny vaovao',
    home: 'Fandraisana',
    learn: 'Fianarana',
    check: 'Hamarinina',
    about: 'Momba',
    login: 'Hiditra',
    register: 'Hisoratra',
    logout: 'Hivoaka',
    welcome: 'Tonga soa',
    theme: 'Teny',
    light: 'Mazava',
    dark: 'Maizina',
    system: 'Rafitra',
    language: 'Fiteny',
    profile: 'Profil',
    dashboard: 'Tabilao',
    getStarted: 'Atombohy',
  },
  fr: {
    appName: 'Mpanolo-tsaina AI',
    slogan: 'Assistant intelligent de littératie médiatique',
    home: 'Accueil',
    learn: 'Apprendre',
    check: 'Vérifier',
    about: 'À propos',
    login: 'Connexion',
    register: 'Inscription',
    logout: 'Déconnexion',
    welcome: 'Bienvenue',
    theme: 'Thème',
    light: 'Clair',
    dark: 'Sombre',
    system: 'Système',
    language: 'Langue',
    profile: 'Profil',
    dashboard: 'Tableau de bord',
    getStarted: 'Commencer',
  },
  en: {
    appName: 'Mpanolo-tsaina AI',
    slogan: 'Intelligent Media Literacy Assistant',
    home: 'Home',
    learn: 'Learn',
    check: 'Check',
    about: 'About',
    login: 'Login',
    register: 'Register',
    logout: 'Logout',
    welcome: 'Welcome',
    theme: 'Theme',
    light: 'Light',
    dark: 'Dark',
    system: 'System',
    language: 'Language',
    profile: 'Profile',
    dashboard: 'Dashboard',
    getStarted: 'Get Started',
  }
};

// Créer le contexte
const LanguageContext = createContext();

// Provider du contexte
export const LanguageProvider = ({ children }) => {
  const [language, setLanguage] = useState('mg'); // Malagasy par défaut

  // Charger la langue sauvegardée
  useEffect(() => {
    const savedLanguage = localStorage.getItem('language');
    if (savedLanguage && translations[savedLanguage]) {
      setLanguage(savedLanguage);
    }
  }, []);

  // Sauvegarder quand la langue change
  useEffect(() => {
    localStorage.setItem('language', language);
  }, [language]);

  // Fonction de traduction
  const t = (key, defaultValue = key) => {
    return translations[language]?.[key] || defaultValue;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
};

// Hook personnalisé
export const useTranslation = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useTranslation must be used within a LanguageProvider');
  }
  return context;
};
